(() => {
  'use strict';
  const el=id=>document.getElementById(id),state={csrf:''};
  async function call(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch('../../../api/vendor/'+path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Account request failed.');return data;}
  function row(label,value){const wrap=document.createElement('div');wrap.className='vc-info-row';const name=document.createElement('span');name.textContent=label;const info=document.createElement('strong');info.textContent=String(value??'—');wrap.append(name,info);return wrap;}
  function status(text,error=false){el('vac-status').textContent=text;el('vac-status').className='vc-status '+(error?'warning':'info');}
  async function load(){try{const identity=await call('auth/me.php');state.csrf=identity.csrf_token||'';const [onboarding,finance]=await Promise.all([call('onboarding.php'),call('finance-summary.php')]);const vendor=identity.vendor||{},application=onboarding.application||{};const profile=el('vac-profile');profile.replaceChildren(row('Display name',vendor.display_name),row('Vendor type',vendor.vendor_type),row('Email',vendor.email),row('Mobile',vendor.mobile),row('Account status',vendor.status));const verification=el('vac-verification');verification.replaceChildren(row('Application',application.reference),row('Review status',application.status?.replaceAll('_',' ')),row('Completion',application.completion_percent+'%'));if(application.decision_reason)verification.append(row('Review note',application.decision_reason));if(['draft','changes_requested'].includes(application.status)){const link=document.createElement('a');link.className='vc-btn small mt-3';link.href='onboarding.php';link.textContent='Continue onboarding';verification.append(link);}const docs=el('vac-documents');docs.replaceChildren();if(!onboarding.documents?.length)docs.textContent='No documents uploaded yet.';else onboarding.documents.forEach(document=>docs.append(row(document.document_type.replaceAll('_',' '),document.verification_status)));const banks=el('vac-banks');banks.replaceChildren();if(!finance.bank_accounts?.length)banks.textContent='No payout bank account on record.';else finance.bank_accounts.forEach(bank=>banks.append(row('Account ending '+bank.account_last4,bank.verification_status)));status('Account details loaded.');}catch(error){status(error.message,true);}}
  el('vac-logout').addEventListener('click',async()=>{try{await call('auth/logout.php','POST',{});location.replace('auth/login.php');}catch(error){status(error.message,true);}});
  load();
})();
